423	/**
424	 * The game port did not open within `GAME_PORT_CHECK_TIMEOUT_MS`. Decide whether
425	 * that means BROKEN or merely SLOW, by asking the guest whether it is still
426	 * doing work, and keep waiting for as long as it is.
427	 *
428	 * Why this exists: the 300s check cannot distinguish "Terraria is sitting on an
429	 * interactive world-selection prompt and will never bind a port" from "ARK is
430	 * 68% through a 22.9 GB SteamCMD download". Both look identical from outside —
431	 * SSH up, game port refused. Before this, both failed the order; measured on
432	 * 2026-09-06, every large Steam-based family was in the second group, so
433	 * healthy servers were being declared failed. Simply raising the timeout would
434	 * fix those at the cost of making genuinely dead servers waste 45 minutes of a
435	 * customer's time before admitting it.
436	 *
437	 * The progress signal is deliberately family-agnostic — no per-image knowledge
438	 * to drift out of date:
439	 *   - the guest's root filesystem is growing (a download/extract is running), OR
440	 *   - the game container has written to its log in the last sample window (world
441	 *     generation, engine startup — work that need not grow the disk much).
442	 * Either counts. `GAME_INSTALL_STALL_LIMIT` consecutive samples with neither is
443	 * what "stopped" means, so a brief pause between download and world-gen phases
444	 * does not end it prematurely.
445	 *
446	 * SAFETY: this runs ONLY after the normal check has already failed, so for every
447	 * family that provisions correctly today this code never executes at all. Any
448	 * error probing the guest returns `ok: false` immediately, i.e. exactly the
449	 * behaviour that existed before — this can only ever turn a failure into a
450	 * success, never the reverse, and `GAME_INSTALL_MAX_WAIT_MS` bounds it absolutely.
451	 */
452	async function waitOutGameInstall(
453	  // Built by the caller from the values IN SCOPE for this provision, not from
454	  // the `server` row it loaded: on a first provision that row still has
455	  // `rootPasswordEnc: null` and `sshPort: null` (both are written to the DB
456	  // *during* this run and the in-memory copy is never refreshed), so
457	  // `serverRootPassword`/`connectionTarget` would resolve to nothing and every
458	  // probe would fail as "the guest stopped answering". Found live 2026-09-06 on
459	  // the first real run of this function.
460	  probeServer: { id: string; rootPassword: string | null; rootPasswordEnc?: string | null; sshPort: number | null; dedicatedIp?: { address: string } | null; node?: { publicIp: string } | null },
461	  checkHost: string,
462	  checkPort: number,
463	  protocol: "tcp" | "udp",
464	  step: (label: string) => Promise<unknown>,
465	  // The game's own systemd unit, so the probe can tell "still installing" from
466	  // "crash-looping". Null for anything with no unit (nothing is judged then).
467	  unitName: string | null,
468	  // Positive in-guest confirmation that the port is really bound — the same one
469	  // the base check uses, so the extended wait cannot end on UDP silence either.
470	  verifyBound: () => Promise<boolean | null>
471	): Promise<{ ok: boolean; reason: string }> {
472	  const deadline = Date.now() + GAME_INSTALL_MAX_WAIT_MS;
473	  let lastUsedKb = -1;
474	  let firstRestarts = -1;
475	  let stalls = 0;
476	  let samples = 0;
477	
478	  // One SSH probe: root-fs used KB, how many bytes the game container has
479	  // logged recently, and how many times its systemd unit has been restarted.
480	  // All plain reads; nothing is mutated on the guest.
481	  const probe = async (): Promise<{ usedKb: number; logBytes: number; restarts: number } | null> => {
482	    try {
483	      return await withServerSsh(probeServer as any, async (conn) => {
484	        const r = await exec(
485	          conn,
486	          `used=$(df --output=used -k / 2>/dev/null | tail -1 | tr -d ' '); ` +
487	            `c=$(docker ps -q 2>/dev/null | head -1); ` +
488	            `lb=0; if [ -n "$c" ]; then lb=$(docker logs --since ${Math.round(GAME_INSTALL_SAMPLE_MS / 1000) + 10}s "$c" 2>&1 | wc -c); fi; ` +
489	            (unitName
490	              ? `nr=$(systemctl show ${unitName} -p NRestarts --value 2>/dev/null); `
491	              : `nr=""; `) +
492	            `case "${"$"}nr" in ''|*[!0-9]*) nr=-1;; esac; ` +
493	            `echo "NXP:${"$"}{used:-0}:${"$"}{lb:-0}:${"$"}nr"`,
494	          QUICK_TIMEOUT_MS
495	        );
496	        const m = /NXP:(\d+):(\d+):(-?\d+)/.exec(r.stdout);
497	        if (!m) return null;
498	        return { usedKb: Number(m[1]), logBytes: Number(m[2]), restarts: Number(m[3]) };
499	      });
500	    } catch {
501	      return null;
502	    }
503	  };
504	
505	  await step("Installing the game — this one is a large download…");
506	
507	  while (Date.now() < deadline) {
508	    const p = await probe();
509	    if (!p) {
510	      return { ok: false, reason: "Could not check whether the install was still running (the guest stopped answering)." };
511	    }
512	    samples++;
513	    if (firstRestarts < 0) firstRestarts = p.restarts;
514	    // A container that keeps dying and being restarted is not installing, and
515	    // its restart output would otherwise read as progress forever — see
516	    // GAME_INSTALL_RESTART_LIMIT. Positive evidence only: an unreadable or
517	    // absent unit reads as -1 and never ends the wait.
518	    if (gameUnitCrashLooping(firstRestarts, p.restarts)) {
519	      return {
520	        ok: false,
521	        reason:
522	          `The game container is crash-looping — its service restarted ${p.restarts - firstRestarts} times ` +
523	          `in ${samples} minute(s) of waiting (systemd NRestarts is now ${p.restarts}), so it was not still installing.`,
524	      };
525	    }
526	    if (lastUsedKb >= 0) {
527	      if (installProgressed({ usedKb: lastUsedKb, logBytes: 0 }, p)) {
528	        stalls = 0;
529	      } else if (++stalls >= GAME_INSTALL_STALL_LIMIT) {
530	        return {
531	          ok: false,
532	          reason:
533	            `The install stopped making progress (${stalls} consecutive minutes with no disk growth and no ` +
534	            `container output, at ${Math.round(p.usedKb / 1024)} MB used), so it was not simply still downloading.`,
535	        };
536	      }
537	    }
538	    lastUsedKb = p.usedKb;
539	
540	    // Waiting and re-checking are the same operation: one sample window of port
541	    // attempts. Returns as soon as the port opens.
542	    const c = await checkGamePortOpen(checkHost, checkPort, protocol, {
543	      timeoutMs: GAME_INSTALL_SAMPLE_MS,
544	      intervalMs: GAME_PORT_CHECK_INTERVAL_MS,
545	      verifyBound,
546	    });
547	    if (c.ok) {
548	      return { ok: true, reason: `still installing for a further ~${samples} min, then the port opened` };
549	    }
550	  }
551	  return {
552	    ok: false,
553	    reason: `It was still installing after ${Math.round(GAME_INSTALL_MAX_WAIT_MS / 60_000)} minutes, which is longer than this platform waits.`,
554	  };
555	}
