  // provision time (or backfilled via scripts/backfill-ssh-management-keys.ts for
  // servers that already existed), whose PUBLIC half is pushed into the guest's
  // authorized_keys. lib/ssh-exec.ts's withServerSsh tries this key BEFORE the
  // root password, so a customer who disables password auth (PasswordAuthentication
  // no) does not break Firewall Sync / SFTP / the database & website tools / staff
  // support access — all of which previously had no fallback and failed outright
  // with ssh2's "All configured authentication methods failed" (real incident,
  // ticket cmuifib3r0yvkhladt4m9ggtp). PER-SERVER, not one shared platform key —
  // a single leaked key only ever exposes the one server it belongs to, matching
  // the blast-radius profile `rootPasswordEnc` already has today, rather than
  // introducing one skeleton key for the whole fleet.
  // `sshManagementKeyEnc` is the OpenSSH-format PRIVATE key, encrypted at rest via
  // lib/crypto-box.ts (same AUTH_SECRET-derived AES-256-GCM box as rootPasswordEnc)
  // — decryptable, not hashed, because withServerSsh must present it on every
  // connection. `sshManagementPublicKey` is the plain authorized_keys LINE (public
  // keys are not secret) — shown to the customer in the dashboard's Root access
  // card so they can verify it themselves without filing a ticket. Both null on
  // any server not yet backfilled; withServerSsh falls back to the password in
  // that case, identical to today's behavior.
  sshManagementKeyEnc   String?
  sshManagementPublicKey String?
  isFree                Boolean             @default(false)
  autoRenew             Boolean             @default(true)
  gameVariant           String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig            Json? // per-game settings values (validated against the family schema)
  // Minecraft-only: `<subdomain>.play.nxeon.cloud`, resolved via a per-server DNS
  // SRV record (worker/game-subdomain.ts) instead of the free tier's shared
  // mc-router — see lib/game-subdomain.ts for the shared name-validation rules.
  // Null until the customer sets one; unique across THIS column only — cross-
  // checked against FreeMinecraftServer.subdomain at the application layer since
  // Postgres can't enforce a unique constraint across two different tables.
  subdomain             String?             @unique
  suspendedNote         String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason         String?
  // Human-readable reason a PROVISION failed terminally, set by the worker on the
  // ERROR path (worker/index.ts). Surfaced on the server detail page's ERROR
  // banner so the customer sees WHAT went wrong instead of a bare red status dot.
  // Cleared when a retry re-enqueues provisioning. Null = never failed (or the
  // failure predates this column).
  provisionError        String?
  // Best-effort, human-readable label for whichever real provisioning phase is
  // running RIGHT NOW (e.g. "Cloning your server…", "Waiting for the game server
  // to start…") — written by worker/index.ts's provision() between real,
  // observable checkpoints (clone / config / start / guest-agent boot / SSH
  // reachable / game port open). Read by lib/provisioning-step.ts and shown by
  // <ProvisioningOverlay/> in place of its cosmetic time-based cycling text.
  // Null = no real signal available yet (falls back to the cosmetic text) or the
  // server isn't mid-provision. Never cleared explicitly — it's simply ignored
  // once status leaves PENDING/PROVISIONING.
  provisioningStep      String?
  expiresAt             DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
model Job {
  id        String    @id @default(cuid())
  type      JobType
  status    JobStatus @default(QUEUED)
  payload   Json?
  error     String?
  progress  Int       @default(0) // 0..100 live task progress (backups/restores)
  step      String? // human-readable current step, e.g. "Creating archive… 42%"
  attempts  Int       @default(0)
  serverId  String?
  server    Server?   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt
}

/// `stripeSessionId` is UNIQUE: it is the idempotency key that makes crediting a
/// Checkout session safe against concurrent confirm-redirect + webhook delivery.
model WalletTransaction {
  stripeSessionId       String?  @unique
  // Same role as stripeSessionId but for OFF-SESSION renewal charges, which have
  // no Checkout session. The UNIQUE constraint — not a read-then-write check — is
  // what makes crediting an auto-charge idempotent when a sweep retries.
  stripePaymentIntentId String?  @unique
  id                    String   @id @default(cuid())
  userId                String
  user                  User     @relation(fields: [userId], references: [id])
  amountCents           Int
  description           String
  createdAt             DateTime @default(now())

226:export async function withServerSsh<T>(
227-  server: SftpServer,
228-  fn: (conn: Client) => Promise<T>
229-): Promise<T> {
230-  const target = connectionTarget(server);
231-  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
232-  const privateKey = serverManagementKey(server);
233-  const password = serverRootPassword(server);
234-  if (!privateKey && !password) throw new Error("Server has no root password on record.");
235-
236-  // Try the per-server management key first (see Server.sshManagementKeyEnc's
237-  // schema doc comment) — falls back to the password if there's no key on file
238-  // yet, or the key is present but the connect itself fails (e.g. a customer
239-  // deleted our line from their own authorized_keys). Only a CONNECT failure
240-  // triggers the fallback — once `fn` is running, its own errors propagate
241-  // normally rather than silently retrying the whole operation a second time.
242-  let conn: Client;
243-  if (privateKey) {
244-    try {
245-      conn = await connectOnce(target, { privateKey });
246-    } catch (e) {
247-      if (!password) throw e;
248-      conn = await connectOnce(target, { password });
249-    }
250-  } else {
251-    conn = await connectOnce(target, { password: password! });
252-  }
253-
254-  try {
255-    return await fn(conn);
256-  } finally {
257-    try {
258-      conn.end();
259-    } catch {
260-      /* best effort */
261-    }
262-  }
263-}
