131	/**
132	 * Serialise allocators across processes with a transaction-scoped advisory lock
133	 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
134	 * transaction — a failing statement inside an open Postgres transaction would
135	 * abort it, so we never speculatively try it in the hot path.
136	 */
137	let advisoryLocks: boolean | null = null;
138	// Two workarounds baked in:
139	//  - the key is a literal, not a bound parameter: a bound JS number can reach
140	//    Postgres as `numeric` and fail to resolve the ...(bigint) overload;
141	//  - pg_advisory_xact_lock() returns `void`, which Prisma's $queryRaw cannot
142	//    deserialize, so it is wrapped in a subselect that yields an int column.
143	const LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})) _lock`;
144	
145	async function lockIpam(tx: Tx): Promise<void> {
146	  if (advisoryLocks === false) return;
147	  await tx.$queryRawUnsafe(LOCK_SQL);
148	}
