150	async function probeAdvisoryLocks(): Promise<void> {
151	  if (advisoryLocks !== null) return;
152	  try {
153	    // Take and immediately release it (xact locks drop at commit). Done once,
154	    // outside the hot path, because a failing statement inside an open
155	    // transaction would abort that transaction.
156	    await db.$transaction(async (tx) => {
157	      await tx.$queryRawUnsafe(LOCK_SQL);
158	    });
159	    advisoryLocks = true;
160	  } catch {
161	    // Not Postgres, or the role lacks permission: the unique-conflict retry
162	    // loop plus in-process reservations remain as the safety net.
163	    advisoryLocks = false;
164	  }
165	}
