182	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
183	    const ip = `${range.subnetPrefix}${i}`;
184	    if (used.has(ip)) continue;
185	    if (isReserved(`ip:${ip}`)) continue;
186	    return ip;
187	  }
188	  throw new Error(
189	    range.nodeId
190	      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
